sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 center;
uniform float angle;
uniform float seamSoft;
uniform float flip;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float2 ctr = center * size;
    float2 n = float2(cos(radians(angle)), sin(radians(angle)));
    float sd = dot(coord - ctr, n);
    float2 mp = coord - 2.0 * sd * n;
    float sgn = flip > 0.5 ? -1.0 : 1.0;
    float k = smoothstep(-max(seamSoft, 0.001), max(seamSoft, 0.001), sd * sgn);
    return fin(c, mix(tex(mp), tex(coord), k), opacity);
}
